  "purpose": {
    "value": "This procedure standardizes intake of customer card-dispute notices before an investigator reviews them.",
    "status": "present",
    "citation": "2"
  },
  "required_steps": {
    "value": [
      "Record the merchant",
      "Record the amount",
      "Record the posting date",
      "Record the customer recognition statement",
      "Record the available receipt",
      "Create a review item and route it to Card Disputes",
      "Do not promise reimbursement"
    ],
    "status": "present",
    "citation": "3"
  },
  "exceptions": {
    "value": "If the customer also reports unrecognized transactions, pause ordinary intake and escalate for possible fraud review.",
    "status": "present",
    "citation": "4"
  }
}

